import { useState, useEffect } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { MapPin, Calendar, Users, Search, ArrowRight, Building2, Home, TreePalm, Warehouse, Hotel } from 'lucide-react'
import { BrandLogo } from '../../components/Header'
import { format, addDays, parseISO } from 'date-fns'
import { Compass, ArrowUpRight, Clock, RefreshCw } from 'lucide-react'
import { supabase } from '../../lib/supabase'
import { optimizeImageUrl, getImageSrcSet } from '../../lib/imageUtils'

// Destination-inspired marketing image; not a listed property. Generated with the built-in image_gen tool.
// Prompt: Use case: photorealistic-natural. Asset type: premium hotel and farm booking website hero photograph, landscape 3:2. Create one exceptionally polished editorial hospitality photograph inspired by the mountainous Kurdistan region of northern Iraq. A welcoming boutique countryside retreat: a beautifully detailed honey-coloured local limestone guesthouse occupying the right third, its open shaded terrace and dark-framed windows warmly lit, two understated linen lounge chairs and a low table with a small Kurdish tea service in the foreground. Restrained handwoven Kurdish kilim textile on one chair, absolutely no logos or lettering. A long narrow turquoise swimming pool leads the eye from foreground toward a lush cultivated valley and dramatic layered rugged limestone mountains in the distance. Mature walnut trees and a few cypress trees, believable cultivated fields; not tropical, no palms, no beach, no Swiss chalet. Composition like a luxury travel magazine photographed on a real full-frame camera with 35mm lens from human eye level, carefully controlled architectural verticals, crisp natural stone texture and realistic water reflections, generous wide mountain backdrop. Late afternoon natural golden light skimming the stone and soft atmospheric blue distance; tasteful sage green, honey gold, deep muted blue. Sophisticated quiet welcoming mood, luxurious but attainable farm holiday, not ostentatious. Photo must feel convincingly real, not an architectural CGI render, not a drawing, not an illustration, not oversaturated. No people, no text, no watermarks, no collage, no graphic overlays, no app UI, no large sun disc. This is a fictional destination-inspired marketing scene, not a depiction of a named real property.
// Embedded WebP keeps this update within the existing source files.
const KURDISTAN_HERO = "data:image/webp;base64,"

interface HotelItem {
  id: string
  name: string
  city: string
  location: string
  images: string[]
  amenities: string[]
  property_type: string
  profit_margin_percentage: number
  currency: string
  room_types: { base_price: number }[]
}

interface Destination {
  id: string
  name: string
}

interface CityFeatured {
  city: string
  hotel_id: string
  hotel_name: string
  featured_image: string
  total_view_seconds: number
}

const propertyTypes = [
  { value: '', labelKey: 'propertyTypes.all', icon: Search },
  { value: 'hotel', labelKey: 'propertyTypes.hotel', icon: Hotel },
  { value: 'farm', labelKey: 'propertyTypes.farm', icon: Warehouse },
  { value: 'motel', labelKey: 'propertyTypes.motel', icon: Building2 },
  { value: 'apartment', labelKey: 'propertyTypes.apartment', icon: Home },
  { value: 'villa', labelKey: 'propertyTypes.villa', icon: TreePalm },
]

export default function HomePage() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const [location, setLocation] = useState('')
  const [checkIn, setCheckIn] = useState('')
  const [checkOut, setCheckOut] = useState('')
  const [guests, setGuests] = useState('2')
  const [propertyType, setPropertyType] = useState('')
  const [hotels, setHotels] = useState<HotelItem[]>([])
  const [destinations, setDestinations] = useState<Destination[]>([])
  const [cityFeatured, setCityFeatured] = useState<CityFeatured[]>([])
  const [galleryHotels, setGalleryHotels] = useState<{ id: string; name: string; image: string }[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState(false)

  const today = format(new Date(), 'yyyy-MM-dd')
  const minCheckout = format(addDays(parseISO(checkIn || today), 1), 'yyyy-MM-dd')

  useEffect(() => {
    fetchDestinations()
    fetchCityFeatured()
    fetchPopularityAndHotels()
  }, [])

  async function fetchDestinations() {
    const { data } = await supabase.from('destinations').select('*').order('name')
    setDestinations(data || [])
  }

  async function fetchPopularityAndHotels() {
    setLoading(true)
    setLoadError(false)
    const { data: popularityData } = await supabase.rpc('get_hotels_with_popularity')
    const allIds = (popularityData || []).map((r: { hotel_id: string }) => r.hotel_id)
    const topIds = allIds.slice(0, 6)
    const galleryIds = allIds.slice(0, 12)

    // Featured hotels (top 6)
    if (topIds.length > 0) {
      const { data, error } = await supabase
        .from('hotels')
        .select('*, room_types(base_price)')
        .in('id', topIds).eq('status', 'active')
      setLoadError(Boolean(error))
      const sorted = (data || []).sort((a, b) => topIds.indexOf(a.id) - topIds.indexOf(b.id))
      setHotels(sorted)
    } else {
      const { data, error } = await supabase
        .from('hotels')
        .select('*, room_types(base_price)')
        .eq('status', 'active')
        .limit(6)
      setLoadError(Boolean(error))
      setHotels(data || [])
    }

    setLoading(false)

    // Gallery (top 12, images only)
    let query = supabase
      .from('hotels')
      .select('id, name, images').eq('status', 'active')
      .not('images', 'eq', '{}')
    if (galleryIds.length > 0) {
      query = query.in('id', galleryIds)
    } else {
      query = query.limit(12)
    }
    const { data: galleryData } = await query
    if (galleryData) {
      const ordered = galleryIds.length > 0
        ? galleryIds.map((id: string) => galleryData.find((h: { id: string }) => h.id === id)).filter(Boolean)
        : galleryData
      const gallery = ordered.flatMap((hotel: { id: string; name: string; images: string[] }) =>
        (hotel.images || []).slice(0, 3).map((img: string) => ({
          id: hotel.id,
          name: hotel.name,
          image: img,
        }))
      ).slice(0, 10)
      setGalleryHotels(gallery)
    }
  }

  async function fetchCityFeatured() {
    const { data } = await supabase.rpc('get_city_featured_hotels')
    setCityFeatured(data || [])
  }

  function getMinPrice(hotel: HotelItem) {
    if (!hotel.room_types || hotel.room_types.length === 0) return null
    const minBase = Math.min(...hotel.room_types.map(r => r.base_price))
    return minBase * (1 + (hotel.profit_margin_percentage || 0) / 100)
  }

  function formatPrice(amount: number, currency: string) {
    if (currency === 'IQD') return `${Math.round(amount).toLocaleString()} IQD`
    return `$${Math.round(amount)}`
  }

  function handleSearch(e: React.FormEvent) {
    e.preventDefault()
    if ((checkIn && checkIn < today) || (checkOut && (!checkIn || checkOut <= checkIn))) return
    const params = new URLSearchParams()
    if (location) params.set('location', location)
    if (checkIn) params.set('checkIn', checkIn)
    if (checkOut) params.set('checkOut', checkOut)
    if (guests) params.set('guests', guests)
    if (propertyType) params.set('type', propertyType)
    navigate(`/search?${params.toString()}`)
  }

  return (
    <div className="home-page">
      <section className="home-hero">
        <div className="hero-inner">
          <div className="hero-copy">
            <p className="eyebrow"><span /> {t('ux.discover')}</p>
            <h1>{t('ux.heroStart')}<br /><em>{t('ux.heroAccent')}</em></h1>
            <p className="hero-description">{t('ux.heroDescription')}</p>
            <a href="#stay-search" className="hero-link">{t('ux.planStay')} <ArrowRight size={18} /></a>
          </div>
          <div className="hero-art">
            <div className="hero-photo">
              <img src={KURDISTAN_HERO} alt={t('ux.heroImageAlt')} width="1100" height="733" fetchPriority="high" decoding="async" />
              <span className="hero-photo-location"><MapPin size={14} />{t('ux.region')}</span>
              <div className="hero-photo-caption"><span>{t('ux.heroImageCaption')}</span><p>{t('ux.artCaption')}</p></div>
            </div>
            <div className="hero-stay-links">
              <Link to="/search?type=hotel"><span className="hero-stay-icon"><Hotel size={21} strokeWidth={1.6}/></span><span><small>{t('ux.cityStays')}</small><strong>{t('propertyTypes.hotel')}</strong></span><ArrowUpRight size={19}/></Link>
              <Link to="/search?type=farm"><span className="hero-stay-icon"><Warehouse size={21} strokeWidth={1.6}/></span><span><small>{t('ux.countryEscapes')}</small><strong>{t('propertyTypes.farm')}</strong></span><ArrowUpRight size={19}/></Link>
            </div>
          </div>
        </div>
        <div className="search-wrap" id="stay-search">
          <form onSubmit={handleSearch} className="stay-search">
            <div className="search-topline"><h2>{t('ux.findStay')}</h2><span><MapPin size={14}/>{t('ux.region')}</span></div>
            <div className="property-tabs" role="group" aria-label={t('search.filterBy')}>
              {propertyTypes.map(pt => <button key={pt.value} type="button" aria-pressed={propertyType === pt.value} onClick={() => setPropertyType(pt.value)} className={propertyType === pt.value ? 'selected' : ''}><pt.icon size={17}/>{t(pt.labelKey)}</button>)}
            </div>
            <div className="search-fields">
              <label className="search-field destination-field"><span><MapPin size={15}/>{t('common.location')}</span>
                <select value={location} onChange={e => setLocation(e.target.value)}>
                  <option value="">{t('common.allDestinations')}</option>
                  {(destinations.length ? destinations : ['Erbil', 'Sulaymaniya', 'Duhok', 'Zakho'].map(name => ({ id: name, name }))).map(d => <option key={d.id} value={d.name}>{d.name}</option>)}
                </select>
              </label>
              <label className="search-field"><span><Calendar size={15}/>{t('common.checkIn')}</span>
                <input type="date" value={checkIn} min={today} required={Boolean(checkOut)} onChange={e => { setCheckIn(e.target.value); if (checkOut && e.target.value >= checkOut) setCheckOut('') }}/>
              </label>
              <label className="search-field"><span><Calendar size={15}/>{t('common.checkOut')}</span>
                <input type="date" value={checkOut} min={minCheckout} required={Boolean(checkIn)} onChange={e => setCheckOut(e.target.value)}/>
              </label>
              <label className="search-field"><span><Users size={15}/>{t('common.guests')}</span>
                <select value={guests} onChange={e => setGuests(e.target.value)}>{Array.from({length: 10}, (_, i) => i + 1).map(n => <option key={n} value={n}>{n} {t(n === 1 ? 'common.guest' : 'common.guests')}</option>)}</select>
              </label>
              <button type="submit" className="search-submit"><Search size={19}/>{t('common.search')}<ArrowRight size={17}/></button>
            </div>
          </form>
          <div className="search-note"><Clock size={15}/><span>{t('ux.flexibleDates')}</span></div>
        </div>
      </section>

      <section className="home-section featured-section">
        <div className="section-heading"><div><p className="eyebrow">{t('ux.takeBreak')}</p><h2>{t('home.featuredProperties')}</h2><p>{t('ux.featuredDescription')}</p></div><Link to="/search" className="text-link">{t('common.viewAllProperties')}<ArrowUpRight size={18}/></Link></div>
        {loading ? <div className="stay-grid" role="status" aria-label={t('common.loading')}>{[1,2,3].map(n => <div key={n} className="stay-skeleton animate-pulse" />)}</div> : loadError ? <div className="home-empty" role="alert"><p>{t('common.errorOccurred')}</p><button onClick={fetchPopularityAndHotels} className="text-link"><RefreshCw size={16}/>{t('ux.retry')}</button></div> : hotels.length === 0 ? <div className="home-empty"><Building2 size={28}/><p>{t('common.noResults')}</p><Link to="/search" className="text-link">{t('common.browseProperties')}<ArrowRight size={16}/></Link></div> : <div className="stay-grid">{hotels.map(hotel => {
          const price = getMinPrice(hotel)
          return <Link key={hotel.id} to={`/hotel/${hotel.id}`} className="stay-card">
            <div className="stay-image"><img src={optimizeImageUrl(hotel.images?.[0] || 'https://images.pexels.com/photos/258154/pexels-photo-258154.jpeg', 800)} srcSet={getImageSrcSet(hotel.images?.[0] || '', [400,800,1200])} sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw" alt={hotel.name} loading="lazy" decoding="async"/><span className="stay-type">{t(`propertyTypes.${hotel.property_type || 'hotel'}`)}</span><span className="stay-arrow"><ArrowUpRight size={19}/></span></div>
            <div className="stay-info"><p className="stay-location"><MapPin size={14}/>{hotel.city}</p><h3>{hotel.name}</h3><div className="stay-price"><span>{t('common.from')}</span><strong>{price !== null ? formatPrice(price, hotel.currency || 'USD') : t('common.priceOnRequest')}</strong>{price !== null && <span>/ {t('common.night')}</span>}</div></div>
          </Link>
        })}</div>}
      </section>

      <section className="destination-section"><div className="home-section">
        <div className="section-heading"><div><p className="eyebrow">{t('ux.closeToHome')}</p><h2>{t('home.exploreDestinations')}</h2><p>{t('home.exploreSubtitle')}</p></div><Compass className="destination-compass" size={44} strokeWidth={1}/></div>
        <div className="destination-grid">{[
          { key: 'erbil', search: 'Erbil' }, { key: 'sulaymaniyah', search: 'Sulaymaniya' }, { key: 'duhok', search: 'Duhok' }, { key: 'zakho', search: 'Zakho' },
        ].map((city, i) => {
          const featured = cityFeatured.find(cf => cf.city?.toLowerCase() === city.search.toLowerCase())
          return <Link key={city.key} to={`/search?location=${city.search}`} className={`destination-card destination-${i}`}>
            {featured?.featured_image && <img src={optimizeImageUrl(featured.featured_image, 600)} alt="" loading="lazy"/>}
            <span className="destination-number">0{i+1}</span><div><h3>{t(`home.${city.key}`)}</h3><p>{t(`home.${city.key}Desc`)}</p></div><ArrowUpRight size={21}/>
          </Link>
        })}</div>
      </div></section>

      {galleryHotels.length > 0 && <section className="home-section"><div className="section-heading"><div><p className="eyebrow">{t('ux.lookInside')}</p><h2>{t('home.insideProperties')}</h2><p>{t('home.insideSubtitle')}</p></div></div><div className="property-gallery">{galleryHotels.map((item, i) => <Link key={`${item.id}-${i}`} to={`/hotel/${item.id}`}><img src={optimizeImageUrl(item.image, 600)} alt={item.name} loading="lazy" decoding="async"/><span>{item.name}<ArrowUpRight size={16}/></span></Link>)}</div></section>}

      <section className="home-section"><div className="host-banner"><div className="host-icon"><Home size={34} strokeWidth={1.4}/></div><div><p className="eyebrow">{t('ux.forHosts')}</p><h2>{t('ux.hostTitle')}</h2><p>{t('ux.hostDescription')}</p></div><Link to="/add-accommodation">{t('ux.listProperty')}<ArrowUpRight size={18}/></Link></div></section>
      <footer className="home-footer"><div className="footer-inner"><div><Link to="/" aria-label="KurdStay"><BrandLogo/></Link><p>{t('ux.footerDescription')}</p><div className="footer-socials"><a href="#" aria-label="TikTok" rel="noopener noreferrer"><svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M19.59 6.69a4.83 4.83 0 0 1-3.77-4.25V2h-3.45v13.67a2.89 2.89 0 0 1-2.88 2.5 2.89 2.89 0 0 1-2.89-2.89 2.89 2.89 0 0 1 2.89-2.89c.28 0 .54.04.79.1v-3.5a6.37 6.37 0 0 0-.79-.05A6.34 6.34 0 0 0 3.15 15a6.34 6.34 0 0 0 6.34 6.34 6.34 6.34 0 0 0 6.34-6.34V8.73a8.19 8.19 0 0 0 4.76 1.52V6.8a4.84 4.84 0 0 1-1-.11z"/></svg></a><a href="#" aria-label="Instagram" rel="noopener noreferrer"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="2" width="20" height="20" rx="5"/><circle cx="12" cy="12" r="5"/><circle cx="17.5" cy="6.5" r="1.5"/></svg></a><a href="#" aria-label="Snapchat" rel="noopener noreferrer"><svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M12.17 2c3.2 0 5.4 2.1 5.59 5.47.04.6-.04 1.61-.1 2.14.3.13.6.2.94.2.44 0 .7-.14.96-.14.22 0 .56.1.56.48 0 .6-.96.88-1.56 1.03-.78.2-.9.3-.84.7.22 1.53 1.3 3.36 3.28 3.82.26.06.5.24.5.5 0 .36-.42.65-.92.82-.6.2-1.37.3-1.6.66-.2.3-.06.72-.44.72-.2 0-.53-.1-1.04-.1-.52 0-.84.06-1.34.4-.7.48-1.32 1.3-2.86 1.3s-2.04-.82-2.84-1.3c-.5-.34-.82-.4-1.34-.4-.5 0-.84.1-1.04.1-.38 0-.24-.42-.44-.72-.23-.36-1-.46-1.6-.66-.5-.17-.92-.46-.92-.82 0-.26.24-.44.5-.5 1.98-.46 3.06-2.3 3.28-3.82.06-.4-.06-.5-.84-.7C4.4 11.08 3.44 10.8 3.44 10.2c0-.38.34-.48.56-.48.26 0 .52.14.96.14.34 0 .64-.07.94-.2-.06-.53-.14-1.54-.1-2.14C6 4.1 8.2 2 11.83 2z"/></svg></a></div></div><div><h3>{t('home.quickLinks')}</h3><Link to="/search">{t('common.browseProperties')}</Link><Link to="/login">{t('home.signIn')}</Link><Link to="/add-accommodation">{t('ux.listProperty')}</Link><a href="/downloads/kurdstay.apk" download>{t('home.downloadApp')}</a></div><div><h3>{t('home.destinations')}</h3>{['Erbil','Sulaymaniya','Duhok','Zakho'].map(city => <Link key={city} to={`/search?location=${city}`}>{city}</Link>)}</div></div><div className="footer-bottom"><span>&copy; {t('home.copyright')}</span><span>{t('home.madeIn')}</span></div></footer>
    </div>
  )
}
